let seed = 7; const rnd = () => { seed = (seed * 16807) % 2147483647; return (seed / 2147483647) - .5; };
const wob = (pts, j) => pts.map((p, i) => (i ? 'L' : 'M') + (p[0] + rnd() * j).toFixed(1) + ' ' + (p[1] + rnd() * j).toFixed(1)).join(' ');
const line = (x1, y1, x2, y2, n) => { const p = []; for (let i = 0; i <= n; i++) p.push([x1 + (x2 - x1) * i / n, y1 + (y2 - y1) * i / n]); return p; };
