const circ = (cx, cy, r) => { const p = []; for (let i = 0; i <= 40; i++) { const a = -1.2 + i / 40 * Math.PI * 2.15; p.push([cx + Math.cos(a) * r * 1.25, cy + Math.sin(a) * r * .8]); } return p; };
